INSERT INTO trails (trail_id, trail_name, alternate_names, desert_riders_trail, bookable, area, park, trailhead_name, trailhead_gps, parking_notes, distance_mi, elevation_gain_ft, highest_point_ft, est_time_easy_pace, est_time_strong_pace, difficulty, activity_type, route_type, technical_rating, optimal_season, viable_season, avoid_season, heat_considerations, water_sources_on_trail, kid_friendly, min_age_rec, dog_friendly, good_for_beginners, good_for_athletes, opening_description, what_makes_it_special, best_for_attributes, trail_day_tip, ridewithgps_link, strava_link, garmin_connect_link, gpx_file_location, photo_references, known_hazards, cell_coverage, emergency_egress_notes, nearest_neighborhood, drive_time_from_downtown_ps, entry_fee_required, guided_eligible) VALUES ('TRAIL-042', 'Palm Canyon Out and Back', NULL, FALSE, TRUE, 'Indian Canyons / South Palm Springs', 'Indian Canyons', 'Palm Canyon', NULL, 'Inside of Indian Canyons.  Park entry fee required.  Per person rates.  Paved parking lot at the Indian Canyons Ranger Station.', 2.0, 217, 983, '1 - 1.5 hrs', '.5 hrs', 2, 'Hiking, Trail Running', 'Out & Back', 2, ARRAY['Jan', 'Feb', 'Mar', 'Nov', 'Dec', 'Apr', 'Oct']::TEXT[], ARRAY['May', 'Sep', 'Jun', 'Jul', 'Aug']::TEXT[], NULL, 'Abundant shade. Very little water running in shoulder season and summer.  Start by 8:30am in shoulder season and summer.  Indian Canyons doesn''t open until 8am.', 'None. Bring minimum 2L of water per person.', TRUE, '4+', 'No', TRUE, FALSE, 'The palm grove is visible before the trail begins. From the ranger station, the canyon below holds hundreds of fan palms, packed along the creek line, the canopy so dense it reads as a single green mass between the canyon walls. Victor Trail climbs the opposite ridge first.
