INSERT INTO trails (trail_id, trail_name, alternate_names, desert_riders_trail, bookable, area, park, trailhead_name, trailhead_gps, parking_notes, distance_mi, elevation_gain_ft, highest_point_ft, est_time_easy_pace, est_time_strong_pace, difficulty, activity_type, route_type, technical_rating, optimal_season, viable_season, avoid_season, heat_considerations, water_sources_on_trail, kid_friendly, min_age_rec, dog_friendly, good_for_beginners, good_for_athletes, opening_description, what_makes_it_special, best_for_attributes, trail_day_tip, ridewithgps_link, strava_link, garmin_connect_link, gpx_file_location, photo_references, known_hazards, cell_coverage, emergency_egress_notes, nearest_neighborhood, drive_time_from_downtown_ps, entry_fee_required, guided_eligible) VALUES ('TRAIL-045', 'Maynard Mine Trail', NULL, FALSE, TRUE, 'Indian Canyons / South Palm Springs', 'Indian Canyons', 'Maynard Mine', NULL, 'Inside of Indian Canyons.  Park entry fee required.  Per person rates.  Dirt parking lot at the Andreas Canyon turnoff.', 5.7, 2236, 2864, '4 - 6 hours', '2.5 - 3 hours', 5, 'Hiking, Trail Running', 'Out & Back', 4, ARRAY['Jan', 'Feb', 'Nov', 'Dec']::TEXT[], ARRAY['Apr', 'Mar', 'Oct']::TEXT[], ARRAY['Jun', 'Jul', 'Aug', 'May', 'Sep']::TEXT[], 'Exposed with little shade. Don''t attempt in shoulder season or summer.  Indian Canyons doesn''t open until 8am.', 'None. Bring minimum 2L per person.', FALSE, '16+', 'No', FALSE, TRUE, 'Most visitors to Palm Springs never hear this trail''s name. The ones who do usually see the hazard sign at the canyon entrance and turn around. What''s beyond it is one of the most layered experiences the Indian Canyons system holds.
INSERT INTO trails (trail_id, trail_name, alternate_names, desert_riders_trail, bookable, area, park, trailhead_name, trailhead_gps, parking_notes, distance_mi, elevation_gain_ft, highest_point_ft, est_time_easy_pace, est_time_strong_pace, difficulty, activity_type, route_type, technical_rating, optimal_season, viable_season, avoid_season, heat_considerations, water_sources_on_trail, kid_friendly, min_age_rec, dog_friendly, good_for_beginners, good_for_athletes, opening_description, what_makes_it_special, best_for_attributes, trail_day_tip, ridewithgps_link, strava_link, garmin_connect_link, gpx_file_location, photo_references, known_hazards, cell_coverage, emergency_egress_notes, nearest_neighborhood, drive_time_from_downtown_ps, entry_fee_required, guided_eligible) VALUES ('TRAIL-046', 'Jo Pond Trail', NULL, FALSE, FALSE, 'Indian Canyons / South Palm Springs', 'Indian Canyons', 'Palm Canyon', NULL, 'Inside of Indian Canyons.  Park entry fee required.  Per person rates.  Paved parking lot at the Indian Canyons Ranger Station.', NULL, NULL, NULL, NULL, NULL, 5, 'Hiking, Trail Running', 'Out & Back', 5, ARRAY['Jan', 'Feb', 'Nov', 'Dec']::TEXT[], ARRAY['Apr', 'Mar', 'Oct']::TEXT[], ARRAY['Jun', 'Jul', 'Aug', 'May', 'Sep']::TEXT[], 'Exposed with little shade. Don''t attempt in shoulder season or summer.  Indian Canyons doesn''t open until 8am.', 'None. Bring minimum 2L of water per person.', FALSE, '16+', 'No', FALSE, TRUE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '1 - No Coverage', NULL, NULL, NULL, TRUE, FALSE);
INSERT INTO trails (trail_id, trail_name, alternate_names, desert_riders_trail, bookable, area, park, trailhead_name, trailhead_gps, parking_notes, distance_mi, elevation_gain_ft, highest_point_ft, est_time_easy_pace, est_time_strong_pace, difficulty, activity_type, route_type, technical_rating, optimal_season, viable_season, avoid_season, heat_considerations, water_sources_on_trail, kid_friendly, min_age_rec, dog_friendly, good_for_beginners, good_for_athletes, opening_description, what_makes_it_special, best_for_attributes, trail_day_tip, ridewithgps_link, strava_link, garmin_connect_link, gpx_file_location, photo_references, known_hazards, cell_coverage, emergency_egress_notes, nearest_neighborhood, drive_time_from_downtown_ps, entry_fee_required, guided_eligible) VALUES ('TRAIL-047', 'Tahquitz Falls', NULL, FALSE, TRUE, 'Indian Canyons / South Palm Springs / San Jacinto Mountains', 'Tahquitz Canyon', 'Tahquitz Falls', NULL, 'Paved lot with about 30 spaces at the Taquitz Falls trailhead.  No fee to park.  Per person fee to hike the trail paid at the trailhead.', 1.8, 281, 867, '1 - 1.5 hrs', '0.5 - 1 hr', 2, 'Hiking, Trail Running', 'Loop', 2, ARRAY['Jan', 'Feb', 'Mar', 'Nov', 'Dec', 'Apr', 'Oct']::TEXT[], ARRAY['May', 'Sep', 'Jun', 'Jul', 'Aug']::TEXT[], NULL, 'Exposed with little shade. Start by 8:30am in shoulder season.  Indian Canyons doesn''t open until 8am.', 'Reliable stream except in summer.  Starts to become stagnant during summer.', TRUE, '4+', 'No', TRUE, TRUE, 'Tahquitz Canyon is Agua Caliente tribal land, and entering it feels like crossing into a different world from the one you parked in. The visitor center collects the entrance fee and checks your water before you head in, a small ritual that signals this place takes itself seriously. The trail follows Tahquitz Creek into the canyon, crossing on low footbridges where you can dangle your feet over the edge and feel the cold moving underneath. Early on, remnants of the original Palm Springs water works appear along the creek: concrete channels and iron fittings that once routed this water into downtown, now sitting quietly as proof of what it took to build a city in the desert. The canyon walls close in gradually, cottonwood trees and wild grapevines crowd the water''s edge, and the falls announce themselves before you see them.', 'The pool at the base of Tahquitz Falls feels like a room. Smooth granite walls rise on three sides, worn pale by centuries of water, and the falls drop into the far end through a narrow slot in the rock. The water is clear and cold and shallow enough at the edges to wade in. Children take their shoes off here without being asked. The falls run most of the year, slowing to a trickle by late summer but rarely going silent. Large boulders ring the pool and the cottonwoods overhead close the sky down to a frame of green and blue. On a weekday the place can feel entirely yours. The loop back to the visitor center climbs slightly above the return trail, giving you a view down through the cottonwood canopy to the creek below and back out toward Palm Springs, the canyon narrowing behind you as the city reappears ahead. The hike is short and gentle. That is not the point. The point is the water, and the feeling of finding it where you least expected to.', ARRAY['Water - streams, pools, falls', 'Wildlife and nature', 'Photography opportunities', 'Moving slow and taking it all in']::TEXT[], NULL, 'https://ridewithgps.com/routes/56148205?privacy_code=pDCFdJdOfPHOd92IEDej0EALLdxVI7no', NULL, NULL, NULL, NULL, 'The running creek, waterfall, and slippery rocks may be challenging for some.  Some short, steep dropoffs are found adjacent to the trail.', '4 - Good', 'Exit on the same trail.  The total route is short so the fastest way out is back to the trailhead.
