INSERT INTO trails (trail_id, trail_name, alternate_names, desert_riders_trail, bookable, area, park, trailhead_name, trailhead_gps, parking_notes, distance_mi, elevation_gain_ft, highest_point_ft, est_time_easy_pace, est_time_strong_pace, difficulty, activity_type, route_type, technical_rating, optimal_season, viable_season, avoid_season, heat_considerations, water_sources_on_trail, kid_friendly, min_age_rec, dog_friendly, good_for_beginners, good_for_athletes, opening_description, what_makes_it_special, best_for_attributes, trail_day_tip, ridewithgps_link, strava_link, garmin_connect_link, gpx_file_location, photo_references, known_hazards, cell_coverage, emergency_egress_notes, nearest_neighborhood, drive_time_from_downtown_ps, entry_fee_required, guided_eligible) VALUES ('TRAIL-052', 'Mumawet and Andreas Fault', NULL, FALSE, TRUE, 'Thousand Palms', 'Coachella Valley Preserve', 'Coachella Valley Preserve Parking Lot', NULL, 'Street parking only along Thousand Palms Canyon Road.  The parking lot is not open for parking.', 1.2, 106, 619, '1 - 1.5 hrs', '.5 - .75 hr', NULL, 'Hiking', 'Out & Back', 1, ARRAY['Jan', 'Feb', 'Mar', 'Nov', 'Dec', 'Apr', 'Oct']::TEXT[], ARRAY['May', 'Sep']::TEXT[], ARRAY['Jun', 'Jul', 'Aug']::TEXT[], 'Exposed with little shade. Start by 8:30am in shoulder season.  Coachella Valley Preserve doesn''t open until 8am.', 'None. Bring minimum 2L of water per person.', TRUE, '4+', 'No', TRUE, TRUE, NULL, NULL, ARRAY['Interesting geology', 'Water - streams, pools, falls', 'Photography opportunities', 'Learning about the place', 'Wildlife and nature']::TEXT[], NULL, 'https://ridewithgps.com/routes/56731563?privacy_code=0PjXfALh1xeXxQeV1TOqlSG9wDMsxeqa', NULL, NULL, NULL, NULL, NULL, '3 - Fair', 'In emergencies, the below contact information should be used.
INSERT INTO trail_landmarks (trail_id, seq, name, mile, description) VALUES ('TRAIL-039', 1, 'Palm Canyon Stream Crossing', 0.1, 'The trail drops immediately to a stream crossing through lush greenery before the climb begins. A jarring contrast to what follows: the last water until Palm Canyon on the return, seven miles away.');
INSERT INTO trail_landmarks (trail_id, seq, name, mile, description) VALUES ('TRAIL-039', 2, 'Palm Canyon Viewpoint', 0.8, 'Victor Trail opens a view across the full Palm Canyon canopy to the West Fork switchbacks on the far canyon wall. The scale of the canyon system becomes visible here for the first time. The East Fork wash is somewhere below, invisible from this angle.');
INSERT INTO trail_landmarks (trail_id, seq, name, mile, description) VALUES ('TRAIL-039', 3, 'Rock Scramble', 1.6, 'The wash begins. The first of several rock scrambles climbs the dry waterfall sections. Turn around after each one: San Jacinto frames itself differently from every elevation as you climb. The canyon walls close in above.');
INSERT INTO trail_landmarks (trail_id, seq, name, mile, description) VALUES ('TRAIL-039', 4, 'Palm Canyon Viewpoint', 5.6, 'Palm Canyon comes back into view just as you begin the descent in earnest. You''ll soon have shade and cooler temperatures once you''re under the palm trees.');
INSERT INTO trail_landmarks (trail_id, seq, name, mile, description) VALUES ('TRAIL-039', 5, 'Palm Canyon Stream Crossing', 7.2, 'The creek runs through granite boulders and fan palms in winter and spring. After miles of dry exposure, the sound of water is unexpected. Cool off before the short walk back to the trailhead.');
INSERT INTO trail_landmarks (trail_id, seq, name, mile, description) VALUES ('TRAIL-041', 1, 'Palm Canyon Viewpoint', 1.4, 'Victor Trail opens a view across the full Palm Canyon canopy to the West Fork switchbacks on the far canyon wall. You''ll be climbing those switchbacks in about a mile. The scale of what''s ahead becomes clear here.');
INSERT INTO trail_landmarks (trail_id, seq, name, mile, description) VALUES ('TRAIL-041', 2, 'Palm Canyon', 2.2, 'The trail drops into Palm Canyon proper: California fan palms, shade, the creek if it''s running. The last cool shade until the West Fork Creek crossing three miles away. Worth a pause before the climb.');
INSERT INTO trail_landmarks (trail_id, seq, name, mile, description) VALUES ('TRAIL-041', 3, 'Palm Stands and Springs', 4.1, 'Halfway up the West Fork switchbacks, natural springs feed isolated stands of palms on the left. Water finding its way to the surface in the middle of the biggest climb on the route. The palms mark exactly where it emerges.');
INSERT INTO trail_landmarks (trail_id, seq, name, mile, description) VALUES ('TRAIL-041', 4, 'West Fork Palm Canyon Creek Crossing', 5.3, 'The West Fork of Palm Canyon Creek in winter and spring: wet soil, lush grasses, green cottonwood trees, wildflowers. Remote, rarely visited, and genuinely surprising after miles of exposed climbing. Pause here before the long ridge traverse back.');
INSERT INTO trail_landmarks (trail_id, seq, name, mile, description) VALUES ('TRAIL-041', 5, 'Murray Canyon Viewpoint', 8.5, 'The Coffman Trail ridge delivers a final view: Murray Canyon palm treetops below, Palm Springs in the distance, the Santa Rosa range beyond. The last landmark before the descent to the trailhead.');
INSERT INTO trail_landmarks (trail_id, seq, name, mile, description) VALUES ('TRAIL-044', 1, 'Palm Canyon Wash Crossing', 0.1, 'A small wash crossing at the base of Victor Trail. In winter and spring, water runs through here before the canyon dries out above. The last water until you descend into the grove on the return.');
INSERT INTO trail_landmarks (trail_id, seq, name, mile, description) VALUES ('TRAIL-044', 2, 'Palm Canyon Viewpoint', 0.8, 'Victor Trail opens a view across the full Palm Canyon canopy: the grove dense and green in the canyon below, the West Fork Trail switchbacks on the far wall. You''ll be walking under that canopy in less than a mile.');
INSERT INTO trail_landmarks (trail_id, seq, name, mile, description) VALUES ('TRAIL-044', 3, 'Palm Canyon Entry', 1.5, 'The descent from Victor Trail brings you into the grove. Within a few steps the trunks close overhead, the temperature drops, and the trail runs between the palms along the creek. Fire-scarred trunks on some trees, new fronds pushing through above. The return to the trailhead is mostly downhill from here.');
INSERT INTO trail_landmarks (trail_id, seq, name, mile, description) VALUES ('TRAIL-045', 1, 'Andreas Canyon Viewpoint', 0.1, 'The trail opens immediately with a view across to Andreas Canyon: canyon walls, fan palms, and the creek hidden below. The starting elevation is already above the canyon you passed on the way to the parking lot.');
INSERT INTO trail_landmarks (trail_id, seq, name, mile, description) VALUES ('TRAIL-045', 2, 'Hidden Andreas Creek Waterfall View', 1.4, 'Just off trail, over a large boulder, a hidden waterfall drops deep into Andreas Canyon below. In winter and spring after recent rain, you''ll hear it before you see it. Easy to walk past without knowing it''s there.');
INSERT INTO trail_landmarks (trail_id, seq, name, mile, description) VALUES ('TRAIL-045', 3, 'Maynard Mine Trail Highpoint', 2.4, 'The high point of the trail before the final descent to the mine. The ridge ahead is steep, often overgrown, with potential rockfall on the trail. Proceed carefully. The mine is less than half a mile from here.');
INSERT INTO trail_landmarks (trail_id, seq, name, mile, description) VALUES ('TRAIL-045', 4, 'Old Mining Generator', 2.8, 'An iron generator mounted to a concrete slab, left exactly where it stopped working when the mine was abandoned. Nobody removed it. It''s been here longer than Palm Springs has been a city.');
INSERT INTO trail_landmarks (trail_id, seq, name, mile, description) VALUES ('TRAIL-045', 5, 'Maynard Mine', 2.9, 'A tunnel dug into the rock, approximately 15 feet deep and 3 feet in diameter. The scramble down to it requires care. Do not enter the mine. This is the turnaround. The full descent back to the trailhead is 2.8 miles from here.');
INSERT INTO trail_landmarks (trail_id, seq, name, mile, description) VALUES ('TRAIL-047', 1, 'Tahquitz Creek Footbridge', 0.4, 'A small footbridge crosses Tahquitz Creek. In winter and spring the creek runs underneath it. The trail follows the creek from here toward the canyon.');
INSERT INTO trail_landmarks (trail_id, seq, name, mile, description) VALUES ('TRAIL-047', 2, 'Place of Wasted Mescal', 0.5, 'Concrete infrastructure with iron remnants marks where Palm Springs'' early water system once operated. The name has outlasted any explanation of where it came from.');
INSERT INTO trail_landmarks (trail_id, seq, name, mile, description) VALUES ('TRAIL-047', 3, 'Tahquitz Falls', 0.9, 'The falls appear around a corner at the end of the trail, tucked into the canyon with no advance warning. In winter and spring after recent rain: water gushing down the rock face into a pool below. In summer and fall: the water is a trickle but the rock face and the canyon are worth the walk on their own.');
INSERT INTO trail_landmarks (trail_id, seq, name, mile, description) VALUES ('TRAIL-047', 4, 'Large Flat Boulders', 1.4, 'A natural rest area on broad flat rock with views northeast over the Palm Springs treetops. A good place to stop on the return.');
INSERT INTO trail_waypoints (trail_id, waypoint_num, mile_marker, description, gps_coordinates, notes) VALUES ('TRAIL-039', 1, 0.0, 'Trailhead. Sharp left onto Fern Canyon Trail, heading toward the stream/wash.', NULL, NULL);
INSERT INTO trail_waypoints (trail_id, waypoint_num, mile_marker, description, gps_coordinates, notes) VALUES ('TRAIL-039', 2, 0.1, 'Landmark A — Stream Crossing. Cross the stream and enjoy the greenery before the climb toward Victor Trail.', NULL, 'Sensory landmark');
INSERT INTO trail_waypoints (trail_id, waypoint_num, mile_marker, description, gps_coordinates, notes) VALUES ('TRAIL-039', 3, 0.3, 'Sharp right onto Victor Trail. Look for the wooden trail sign to confirm the route.', NULL, 'Navigation note');
INSERT INTO trail_waypoints (trail_id, waypoint_num, mile_marker, description, gps_coordinates, notes) VALUES ('TRAIL-039', 4, 0.8, 'Landmark B — Palm Canyon Viewpoint. Gaze across the treetops of Palm Canyon to the West Fork Trail switchbacks on the far canyon wall.', NULL, 'Primary landmark');
INSERT INTO trail_waypoints (trail_id, waypoint_num, mile_marker, description, gps_coordinates, notes) VALUES ('TRAIL-039', 5, 1.5, 'Slight right onto Vandeventer Trail and continue downhill, then left back onto Victor Trail, then slight left toward the rock scramble in the wash.', NULL, 'Navigation note — several turns in quick succession');
INSERT INTO trail_waypoints (trail_id, waypoint_num, mile_marker, description, gps_coordinates, notes) VALUES ('TRAIL-039', 6, 1.6, 'Landmark C — Rock Scramble. First of several rock scrambles climbing the wash. Climb carefully — some sections open to San Jacinto mountain views behind you.', NULL, 'Primary landmark / caution');
INSERT INTO trail_waypoints (trail_id, waypoint_num, mile_marker, description, gps_coordinates, notes) VALUES ('TRAIL-039', 7, 3.4, 'Sharp left onto East Fork Trail.', NULL, NULL);
INSERT INTO trail_waypoints (trail_id, waypoint_num, mile_marker, description, gps_coordinates, notes) VALUES ('TRAIL-039', 8, 4.6, 'Left onto Vandeventer Trail, heading back toward Palm Canyon.', NULL, NULL);
INSERT INTO trail_waypoints (trail_id, waypoint_num, mile_marker, description, gps_coordinates, notes) VALUES ('TRAIL-039', 9, 6.1, 'Left onto Vandeventer Trail, descending into Palm Canyon.', NULL, NULL);
INSERT INTO trail_waypoints (trail_id, waypoint_num, mile_marker, description, gps_coordinates, notes) VALUES ('TRAIL-039', 10, 6.2, 'Sharp right onto Palm Canyon Trail toward the Palm Trees and back to the parking lot.', NULL, NULL);
INSERT INTO trail_waypoints (trail_id, waypoint_num, mile_marker, description, gps_coordinates, notes) VALUES ('TRAIL-039', 11, 6.7, 'Keep right, continuing onto Palm Canyon Trail.', NULL, NULL);
INSERT INTO trail_waypoints (trail_id, waypoint_num, mile_marker, description, gps_coordinates, notes) VALUES ('TRAIL-039', 12, 7.1, 'Right, then sharp right, staying on Palm Canyon Trail.', NULL, NULL);
INSERT INTO trail_waypoints (trail_id, waypoint_num, mile_marker, description, gps_coordinates, notes) VALUES ('TRAIL-039', 13, 7.2, 'Landmark D — Palm Canyon Creek Crossing. Cool water and palm trees if the creek is running (winter/spring).', NULL, 'Sensory landmark');
INSERT INTO trail_waypoints (trail_id, waypoint_num, mile_marker, description, gps_coordinates, notes) VALUES ('TRAIL-039', 14, 7.2, 'Left onto Fern Canyon Trail, heading back to the trailhead.', NULL, NULL);
INSERT INTO trail_waypoints (trail_id, waypoint_num, mile_marker, description, gps_coordinates, notes) VALUES ('TRAIL-039', 15, 7.3, 'End of route. Back at the trailhead.', NULL, NULL);
INSERT INTO trail_waypoints (trail_id, waypoint_num, mile_marker, description, gps_coordinates, notes) VALUES ('TRAIL-041', 1, 0.0, 'Trailhead. Start of route.', NULL, NULL);
INSERT INTO trail_waypoints (trail_id, waypoint_num, mile_marker, description, gps_coordinates, notes) VALUES ('TRAIL-041', 2, 0.0, 'Landmark A — Street Crossing. Be careful crossing the street to reach the Alexander Trail on the other side — watch for cars.', NULL, 'Caution — street crossing');
INSERT INTO trail_waypoints (trail_id, waypoint_num, mile_marker, description, gps_coordinates, notes) VALUES ('TRAIL-041', 3, 0.5, 'Landmark B — Alexander Trail Wash Entry. Leaving the dirt parking lot, the trail drops into the wash and can be hard to locate — look for trail signs and footprints close to the canyon wall on the opposite side of the wash.', NULL, 'Navigation note — trail hard to find');
INSERT INTO trail_waypoints (trail_id, waypoint_num, mile_marker, description, gps_coordinates, notes) VALUES ('TRAIL-041', 4, 0.9, 'Landmark C — Victor Trail Intersection. Continue straight onto Victor Trail. Look for a trail sign at this intersection to confirm your route.', NULL, 'Navigation note');
INSERT INTO trail_waypoints (trail_id, waypoint_num, mile_marker, description, gps_coordinates, notes) VALUES ('TRAIL-041', 5, 1.4, 'Landmark D — Palm Canyon Viewpoint. Look across the treetops of Palm Canyon and see the switchbacks of the West Fork Trail on the other side — you''ll be climbing those switchbacks soon.', NULL, 'Primary landmark');
INSERT INTO trail_waypoints (trail_id, waypoint_num, mile_marker, description, gps_coordinates, notes) VALUES ('TRAIL-041', 6, 2.1, 'Slight right onto Vandeventer Trail, then sharp right onto Palm Canyon Trail.', NULL, NULL);
INSERT INTO trail_waypoints (trail_id, waypoint_num, mile_marker, description, gps_coordinates, notes) VALUES ('TRAIL-041', 7, 2.2, 'Landmark E — Palm Canyon. Take a moment to enjoy the California fan palms in Palm Canyon — this is the last shade you''ll have for several miles once you leave the canyon.', NULL, 'Sensory landmark');
INSERT INTO trail_waypoints (trail_id, waypoint_num, mile_marker, description, gps_coordinates, notes) VALUES ('TRAIL-041', 8, 2.7, 'Keep right, then keep right again to continue on Palm Canyon Trail.', NULL, NULL);
INSERT INTO trail_waypoints (trail_id, waypoint_num, mile_marker, description, gps_coordinates, notes) VALUES ('TRAIL-041', 9, 2.9, 'Sharp left onto the switchbacks of West Fork Trail.', NULL, 'Navigation note — major turn onto the climb');
INSERT INTO trail_waypoints (trail_id, waypoint_num, mile_marker, description, gps_coordinates, notes) VALUES ('TRAIL-041', 10, 4.1, 'Landmark F — Palm Stands and Springs. To the left, stands of palm trees fed by natural springs support the lush growth here.', NULL, 'Sensory landmark');
INSERT INTO trail_waypoints (trail_id, waypoint_num, mile_marker, description, gps_coordinates, notes) VALUES ('TRAIL-041', 11, 5.0, 'Right onto West Fork Trail. Look for trail signs to confirm.', NULL, NULL);
INSERT INTO trail_waypoints (trail_id, waypoint_num, mile_marker, description, gps_coordinates, notes) VALUES ('TRAIL-041', 12, 5.3, 'Landmark G — West Fork Palm Canyon Creek Crossing. In winter/spring the lushness here is surprising — wet soil, lush grasses, green cottonwood trees, wildflowers. Pause and enjoy; not many will visit this place.', NULL, 'Sensory landmark — signature moment');
INSERT INTO trail_waypoints (trail_id, waypoint_num, mile_marker, description, gps_coordinates, notes) VALUES ('TRAIL-041', 13, 8.4, 'Right onto Coffman Trail, heading back toward the trailhead and vehicle.', NULL, NULL);
INSERT INTO trail_waypoints (trail_id, waypoint_num, mile_marker, description, gps_coordinates, notes) VALUES ('TRAIL-041', 14, 8.5, 'Landmark H — Murray Canyon Viewpoint. Look down on the palm tree tops of Murray Canyon and to Palm Springs in the distance before the final descent.', NULL, 'Primary landmark');
INSERT INTO trail_waypoints (trail_id, waypoint_num, mile_marker, description, gps_coordinates, notes) VALUES ('TRAIL-041', 15, 9.2, 'Right onto Coffman Trail.', NULL, NULL);
INSERT INTO trail_waypoints (trail_id, waypoint_num, mile_marker, description, gps_coordinates, notes) VALUES ('TRAIL-041', 16, 9.5, 'End of route. Back at the trailhead and vehicle.', NULL, NULL);
INSERT INTO trail_waypoints (trail_id, waypoint_num, mile_marker, description, gps_coordinates, notes) VALUES ('TRAIL-044', 1, 0.0, 'Trailhead. Sharp left onto Fern Canyon Trail.', NULL, NULL);
INSERT INTO trail_waypoints (trail_id, waypoint_num, mile_marker, description, gps_coordinates, notes) VALUES ('TRAIL-044', 2, 0.1, 'Landmark A — Palm Canyon Wash Crossing. In winter/spring, enjoy water trickling through here as you begin the climb toward Victor Trail.', NULL, 'Sensory landmark');
INSERT INTO trail_waypoints (trail_id, waypoint_num, mile_marker, description, gps_coordinates, notes) VALUES ('TRAIL-044', 3, 0.3, 'Sharp right onto Victor Trail.', NULL, NULL);
INSERT INTO trail_waypoints (trail_id, waypoint_num, mile_marker, description, gps_coordinates, notes) VALUES ('TRAIL-044', 4, 0.8, 'Landmark B — Palm Canyon Viewpoint. A unique view of Palm Canyon from above and the West Fork Trail switchbacks on the far side of the canyon.', NULL, 'Primary landmark');
INSERT INTO trail_waypoints (trail_id, waypoint_num, mile_marker, description, gps_coordinates, notes) VALUES ('TRAIL-044', 5, 1.5, 'Continue right and downhill onto Vandeventer Trail, entering Palm Canyon, then sharp right onto Palm Canyon Trail.', NULL, NULL);
INSERT INTO trail_waypoints (trail_id, waypoint_num, mile_marker, description, gps_coordinates, notes) VALUES ('TRAIL-044', 6, 1.5, 'Landmark C — Palm Canyon. Welcome to Palm Canyon — enjoy the mostly downhill trip back to the parking lot and the Indian Canyons Ranger Station, under tree canopy the whole way.', NULL, 'Sensory landmark');
INSERT INTO trail_waypoints (trail_id, waypoint_num, mile_marker, description, gps_coordinates, notes) VALUES ('TRAIL-044', 7, 2.1, 'Keep right to continue on Palm Canyon Trail.', NULL, NULL);
INSERT INTO trail_waypoints (trail_id, waypoint_num, mile_marker, description, gps_coordinates, notes) VALUES ('TRAIL-044', 8, 2.4, 'Sharp left onto Palm Canyon Trail, climbing up to the Indian Canyons Ranger Station and parking lot.', NULL, NULL);
INSERT INTO trail_waypoints (trail_id, waypoint_num, mile_marker, description, gps_coordinates, notes) VALUES ('TRAIL-044', 9, 2.5, 'End of route. Back at the trailhead.', NULL, NULL);
INSERT INTO trail_waypoints (trail_id, waypoint_num, mile_marker, description, gps_coordinates, notes) VALUES ('TRAIL-045', 1, 0.0, 'Trailhead. Start of route.', NULL, NULL);
INSERT INTO trail_waypoints (trail_id, waypoint_num, mile_marker, description, gps_coordinates, notes) VALUES ('TRAIL-045', 2, 0.1, 'Landmark A — Andreas Canyon Viewpoint. A unique view of the canyon walls and palm trees of Andreas Canyon.', NULL, 'Primary landmark');
INSERT INTO trail_waypoints (trail_id, waypoint_num, mile_marker, description, gps_coordinates, notes) VALUES ('TRAIL-045', 3, 0.6, 'Keep left onto Maynard Mine Trail.', NULL, NULL);
INSERT INTO trail_waypoints (trail_id, waypoint_num, mile_marker, description, gps_coordinates, notes) VALUES ('TRAIL-045', 4, 1.1, 'Slight right, continuing onto Maynard Mine Trail.', NULL, NULL);
INSERT INTO trail_waypoints (trail_id, waypoint_num, mile_marker, description, gps_coordinates, notes) VALUES ('TRAIL-045', 5, 1.4, 'Landmark B — Hidden Andreas Creek Waterfall View. Just off the trail, over a large boulder, a view of a hidden waterfall deep in Andreas Canyon below. In winter/spring after rain you''ll hear the waterfall carry across the canyon.', NULL, 'Sensory landmark');
INSERT INTO trail_waypoints (trail_id, waypoint_num, mile_marker, description, gps_coordinates, notes) VALUES ('TRAIL-045', 6, 2.4, 'Landmark C — Maynard Mine Trail Highpoint. The trail here follows a steep, often-overgrown ridgeline to the mine. May have rockfall — use caution beyond this point.', NULL, 'Caution — technical terrain');
INSERT INTO trail_waypoints (trail_id, waypoint_num, mile_marker, description, gps_coordinates, notes) VALUES ('TRAIL-045', 7, 2.8, 'Landmark D — Old Mining Generator. An old iron generator from mining operations, mounted to a concrete slab.', NULL, 'Primary landmark');
INSERT INTO trail_waypoints (trail_id, waypoint_num, mile_marker, description, gps_coordinates, notes) VALUES ('TRAIL-045', 8, 2.9, 'Landmark E — Maynard Mine. A small mine tunnel about 15 feet deep and 3 feet in diameter. Do not enter the mine; use extreme care on the scramble down to it.', NULL, 'Primary landmark / safety note — do not enter mine');
INSERT INTO trail_waypoints (trail_id, waypoint_num, mile_marker, description, gps_coordinates, notes) VALUES ('TRAIL-045', 9, 5.7, 'End of route. Return to the trailhead (out and back).', NULL, NULL);
INSERT INTO trail_waypoints (trail_id, waypoint_num, mile_marker, description, gps_coordinates, notes) VALUES ('TRAIL-047', 1, 0.0, 'Trailhead. Start of route at the visitor center (entrance fee paid here).', NULL, NULL);
INSERT INTO trail_waypoints (trail_id, waypoint_num, mile_marker, description, gps_coordinates, notes) VALUES ('TRAIL-047', 2, 0.4, 'Landmark 1 — Tahquitz Creek Footbridge. A small footbridge crosses Tahquitz Creek; in winter/spring the creek runs underneath it.', NULL, 'Sensory landmark');
INSERT INTO trail_waypoints (trail_id, waypoint_num, mile_marker, description, gps_coordinates, notes) VALUES ('TRAIL-047', 3, 0.5, 'Landmark 2 — Place of Wasted Mescal. Concrete infrastructure with iron remnants marks where Palm Springs'' early water system once operated.', NULL, 'Historical landmark');
INSERT INTO trail_waypoints (trail_id, waypoint_num, mile_marker, description, gps_coordinates, notes) VALUES ('TRAIL-047', 4, 0.9, 'Landmark 3 — Tahquitz Falls. The falls appear around a corner at the end of the trail, tucked into the canyon with no advance warning.', NULL, 'Primary landmark — destination point');
INSERT INTO trail_waypoints (trail_id, waypoint_num, mile_marker, description, gps_coordinates, notes) VALUES ('TRAIL-047', 5, 1.4, 'Landmark 4 — Large Flat Boulders. A natural rest area on broad flat rock with views northeast over the Palm Springs treetops. Good spot to stop on the return.', NULL, 'Rest stop');
INSERT INTO trail_waypoints (trail_id, waypoint_num, mile_marker, description, gps_coordinates, notes) VALUES ('TRAIL-047', 6, 1.8, 'End of route. Back at the visitor center.', NULL, NULL);
